// Bundles the message editor (editor/editor.ts) into one script and writes it into
// src/compose/editorBundle.generated.ts, so the compose screen can load it into its web view without a network.
// Run `npm run build:editor` after changing the editor; CI checks that the generated file is current.
import { writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'rolldown'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')

const result = await build({
  input: resolve(root, 'editor/editor.ts'),
  platform: 'browser',
  write: false,
  output: { format: 'iife', minify: true, comments: { legal: false } },
})
const chunk = result.output.find((item) => item.type === 'chunk')
if (chunk === undefined) {
  throw new Error('The editor bundle came out empty.')
}

const source = `// Generated by scripts/build-editor.mjs from editor/editor.ts. Do not edit; run \`npm run build:editor\`.
export const EDITOR_SCRIPT = ${JSON.stringify(chunk.code)}
`
await writeFile(resolve(root, 'src/compose/editorBundle.generated.ts'), source)
console.log(`Editor bundle: ${Math.round(chunk.code.length / 1024)} KB`)
